abbrev log2 (x : ℝ) : ℝ := Real.logb 2 x
def rounds (m : ℕ) : ℕ := Nat.clog 2 (1000 * m)
theorem log2_four_pow (t : ℕ) : log2 ((4 : ℝ)^t) = 2 * t

def denominator (k t : ℕ) : ℕ := 4^t * 2^(t*(k-1))
def numerator (k t : ℕ) (z : Fin k → WalshIndex t → Bool) : ℤ :=
  integerWalshProduct z
theorem forrelation_integer_ratio (hk : 1 ≤ k) :
  0 < denominator k t ∧
  forrelationScalar k t z = (numerator k t z:ℝ) / denominator k t

def tournamentRounds (m : ℕ) : ℕ := Nat.clog 2 (1000*m)
def tournamentEpsilon (m : ℕ) : ℝ := 1/(1000*(tournamentRounds m:ℝ))
theorem tournamentParameters (hm : 2 ≤ m) :
  0 < tournamentEpsilon m ∧ tournamentEpsilon m < 1/2 ∧
  (2*m:ℝ)/2^(tournamentRounds m) ≤ 1/500

def IsHeavy (L : ℕ) (A : Cslib.DecisionTree (BitLoc cfg) Bool)
    (ω : DummySample cfg) (i : Fin cfg.m) : Prop :=
  L < (A.queryTrace (dummyInput ω)).countP (isAddressQueryInColumn i)

theorem maximal_monomial_parity_restriction (f : Bits n → Bool) (hd : 1 ≤ degree f) :
  ∃ ρ : SubcubeRestriction n (degree f), ∃ σ : Bool,
    let g := fun x => f (ρ.embed x)
    let U := Finset.univ.filter (fun x => g x = Bool.xor σ (parity x))
    2^(degree f-1) < U.card ∧
    ∀ x ∈ U, ∀ y ∈ U, hammingDist x y = 1 → g x ≠ g y
